/// A set of [`CardKeyword`]s: one bit per keyword, at its discriminant.
///
/// Bit 0 is unused, because the game's zero is `None` and that is not
/// a keyword. Using the discriminant anyway keeps a bit meaning the
/// same thing here as it does there.
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub struct KeywordSet(u8);

impl KeywordSet {
    /// Every member, in the enum's own order.
    const MEMBERS: [CardKeyword; 7] = [
        CardKeyword::Exhaust,
        CardKeyword::Ethereal,
        CardKeyword::Innate,
        CardKeyword::Unplayable,
        CardKeyword::Retain,
        CardKeyword::Sly,
        CardKeyword::Eternal,
    ];

    pub const fn new(members: &[CardKeyword]) -> Self {
        let mut bits = 0u8;
        let mut i = 0;
        while i < members.len() {
            bits |= 1u8 << members[i] as u8;
            i += 1;
        }
        Self(bits)
    }

    pub const fn contains(self, member: CardKeyword) -> bool {
        self.0 & (1u8 << member as u8) != 0
    }

    /// The members, in the enum's own order.
    pub fn iter(self) -> impl Iterator<Item = CardKeyword> {
        Self::MEMBERS.into_iter().filter(move |&m| self.contains(m))
    }
}

impl std::fmt::Debug for KeywordSet {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_set().entries(self.iter()).finish()
    }
}

impl sts2_core::FlagSet for KeywordSet {
    type Member = CardKeyword;

    const MEMBERS: &'static [CardKeyword] = &Self::MEMBERS;

    fn from_members(members: &[CardKeyword]) -> Self {
        Self::new(members)
    }

    fn contains(self, member: CardKeyword) -> bool {
        Self::contains(self, member)
    }
}

/// A set of [`CardType`]s: one bit per type, at its discriminant.
///
/// Bit 0 is unused, because the game's zero is `None` and that is
/// not a type a card can have. Using the discriminant anyway keeps
/// a bit meaning the same thing here as it does there.
